from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color != background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            component = []
            while q:
                y, x = q.popleft()
                component.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == color and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        q.append((ny, nx))

            edge_cells = {
                'top': sorted(x for y, x in component if y == 0),
                'bottom': sorted(x for y, x in component if y == h - 1),
                'left': sorted(y for y, x in component if x == 0),
                'right': sorted(y for y, x in component if x == w - 1),
            }
            sides = {s: ps for s, ps in edge_cells.items() if ps}
            enclosed = not sides
            # The board frame can complete an enclosure when a component
            # touches exactly one edge and is capped at both ends on that edge.
            if len(sides) == 1:
                side, positions = next(iter(sides.items()))
                edge_len = w if side in ('top', 'bottom') else h
                runs = []
                for p in positions:
                    if not runs or p > runs[-1][-1] + 1:
                        runs.append([p])
                    else:
                        runs[-1].append(p)
                enclosed = bool(runs) and all(
                    run[0] > 0 and run[-1] < edge_len - 1 for run in runs
                )
            if enclosed:
                for y, x in component:
                    out[y][x] = 4
    return out
